    case 36: /* OR */
    case 37: /* ALGORITHM */
    case 38: /* SQL */
    case 39: /* DEFINER */
    case 40: /* EVENT */
    case 41: /* PROCEDURE */
    case 42: /* TRIGGER */
    case 43: /* USER */
    case 44: /* ROLE */
    case 45: /* DATABASE */
    case 46: /* SCHEMA */
    case 47: /* IF */
    case 48: /* DROP */
    case 49: /* PREPARE */
    case 50: /* ON */
    case 51: /* TABLES */
    case 52: /* COMMA */
    case 53: /* MASTER */
    case 54: /* RESTRICT */
    case 55: /* CASCADE */
    case 56: /* ENGINE */
    case 57: /* ALTER */
    case 58: /* INSTANCE */
    case 59: /* RENAME */
    case 60: /* TO */
    case 61: /* TRUNCATE */
    case 62: /* LOAD */
    case 63: /* DATA */
    case 64: /* XML */
    case 65: /* INTO */
    case 66: /* CACHE */
    case 67: /* LOW_PRIORITY */
    case 68: /* LOCAL */
    case 69: /* CONCURRENT */
    case 70: /* IGNORE */
